    vector<pair<int, int>> tasks(n);
    for (int i = 0; i < n; i++) tasks[i] = make_pair(a[i], b[i]);

    sort(tasks.rbegin(), tasks.rend());

    vector<pair<int, int>> dp(n + 1, make_pair(0, 0));
    dp[0] = make_pair(0, 1);
    for (int i = 0; i < n; i++) {
        dp[i + 1] = dp[i];
