        int u, v;
        cin >> u >> v;
        u--, v--;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    cnt.resize(n);
    dfs(0, -1);

    cout << dfs2(0, -1) << endl;

    return 0;
