    cin.tie(nullptr);

    int x, y;
    while (cin >> x >> y && x != 0 && y != 0) {
        vector<pair<int, char>> edges;
        unordered_map<int, unordered_map<char, vector<int>>> graph;
        for (int i = 0; i < y; ++i) {
            int p;
            char P;
            int q;
            char Q;
            cin >> p >> P >> q >> Q;
            edges.emplace_back(p, P);
            edges.emplace_back(q, Q);
            graph[p][P].push_back(q);
            graph[q][Q].push_back(p);
        }

        vector<string> configs(x), target(x);
        for (int i = 0; i < x; ++i) {
            cin >> configs[i];
        }
        for (int i = 0; i < x; ++i) {
            cin >> target[i];
        }

        unordered_map<State, int, Hash> distances;
        queue<State> q;
        State initial;
        initial.configs = configs;
        initial.moves = 0;
        distances[initial] = 0;
        q.push(initial);

        while (!q.empty()) {
            State state = q.front();
            q.pop();
            if (state.configs == target) {
                cout << state.moves << '\n';
                break;
            }

            unordered_map<State, int, Hash> next_states;
            get_next_states(state, edges, next_states);
            for (const auto& next_state : next_states) {
                if (distances.find(next_state.first) == distances.end() || distances[next_state.first] > next_state.second) {
                    distances[next_state.first] = next_state.second;
                    q.push(next_state.first);
                }
            }
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 4005;

int dp[2][MAXN][MAXN];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = s.size(), m = t.size();

    memset(dp, -1, sizeof(dp));
    dp[0][0][0] = 0;
    dp[1][0][0] = 0;

    int now = 0;
    for (int i = 1; i <= n; ++i) {
        now ^= (s[i - 1] - '0');
        dp[now][i][0] = 0;
    }

    now = 0;
    for (int i = 1; i <= m; ++i) {
        now ^= (t[i - 1] - '0');
        dp[now][0][i] = 0;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            for (int k = 0; k < 2; ++k) {
                if (dp[k][i - 1][j] != -1) {
                    dp[k][i][j] = min(dp[k][i][j], (s[i - 1] - '0') ^ k);
                }
                if (dp[k][i][j - 1] != -1) {
                    dp[k][i][j] = min(dp[k][i][j], (t[j - 1] - '0') ^ k);
                }
            }
        }
    }

    string ans;
    int x = n, y = m, now1 = 0;
    while (x > 0 || y > 0) {
        if (x > 0 && dp[0][x - 1][y] != -1 && dp[1][x - 1][y] != -1) {
            if (dp[0][x - 1][y] < dp[1][x - 1][y]) {
                ans += '0';
                now1 = 0;
            } else {
                ans += '1';
                now1 = 1;
            }
            --x;
        } else if (y > 0 && dp[0][x][y - 1] != -1 && dp[1][x][y - 1] != -1) {
            if (dp[0][x][y - 1] < dp[1][x][y - 1]) {
                ans += '0';
                now1 = 0;
            } else {
                ans += '1';
                now1 = 1;
            }
            --y;
        } else if (x > 0) {
            ans += '0';
            now1 = 0;
            --x;
        } else {
            ans += '0';
            now1 = 0;
            --y;
        }
    }

    reverse(ans.begin(), ans.end());

    cout << ans << '\n';

    return 0;
}

