int main() {
    int d, w;
    while (cin >> d >> w) {
        if (d == 0 && w == 0) break;

        vector<vector<int>> elevations(d, vector<int>(w));
        for (int i = 0; i < d; i++) {
            for (int j = 0; j < w; j++) {
                cin >> elevations[i][j];
            }
        }

        int maxCapacity = 0;
        for (int i = 1; i < d - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                for (int x = i - 1; x <= i + 1; x++) {
                    for (int y = j - 1; y <= j + 1; y++) {
                        if (x == i && y == j) continue;

                        int capacity = 0;
                        int minElevation = elevations[x][y];
                        bool isValid = true;

                        for (int a = i - 1; a <= i + 1; a++) {
                            for (int b = j - 1; b <= j + 1; b++) {
                                if (a == i && b == j) {
                                    capacity += minElevation - elevations[a][b];
                                } else {
                                    if (elevations[a][b] <= elevations[i][j]) {
                                        isValid = false;
                                    }
                                    if (elevations[a][b] < minElevation) {
                                        minElevation = elevations[a][b];
                                    }
                                }
                            }
                        }

                        if (isValid && capacity > maxCapacity) {
                            maxCapacity = capacity;
                        }
                    }
                }
            }
        }

        cout << maxCapacity << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 25;
int grid[MAXN][MAXN];
int memo[MAXN][MAXN][2]; // 2 for not taken, 1 for taken
int w, h;

int dp(int i, int j, bool taken) {
    if (i >= h) return 0;
    if (j >= w) return dp(i + 1, 0, 0);
    int& ret = memo[i][j][taken];
    if (ret != -1) return ret;

    int exclude = dp(i, j + 1, taken);
    int include = 0;
    if (!taken && (i == 0 || j == 0 || grid[i - 1][j - 1] == 0)) {
        include = grid[i][j] + dp(i, j + 1, 1);
    }
    return ret = max(include, exclude);
}

int solve() {
    memset(memo, -1, sizeof memo);
    return dp(0, 0, 0);
}

int main() {
    int t;
    cin >> t;
    for (int tc = 1; tc <= t; ++tc) {
        cin >> w >> h;
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                cin >> grid[i][j];
                if (j > 0) grid[i][j] += grid[i][j - 1];
            }
        }
        int ans = solve();
        cout << "Case " << tc << ": " << ans << endl;
    }
    return 0;
}

