int n, q;
int par[MAXN], rank[MAXN];
int ans[MAXN];
vector<int> g[MAXN];

int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
}

void merge(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) par[x] = y;
    else if (rank[x] > rank[y]) par[y] = x;
    else {
        par[y] = x;
        rank[x]++;
    }
}

void dfs(int u, int p, int d) {
    for (int v : g[u]) {
        if (v == p) continue;
        dfs(v, u, d + 1);
    }
}

