#define MOD 998244353

ll fastpow(ll a, ll n, ll mod) {
    if (n == 0) return 1;
    if (n % 2 == 1) return (a * fastpow(a, n - 1, mod)) % mod;
    ll temp = fastpow(a, n / 2, mod);
    return (temp * temp) % mod;
}

ll inv(ll a, ll mod) {
    return fastpow(a, mod - 2, mod);
}

