const int mod = 998244353;

inline int add(int x, int y) {
    x += y;
    if (x >= mod) {
        x -= mod;
    }
    return x;
}

inline int sub(int x, int y) {
    x -= y;
    if (x < 0) {
        x += mod;
    }
    return x;
}

inline int mul(int x, int y) {
    return (long long)x * y % mod;
}

inline int qpow(int x, int y) {
    int ans = 1;
    for (; y; y >>= 1, x = mul(x, x)) {
        if (y & 1) {
            ans = mul(ans, x);
        }
    }
    return ans;
}

inline int inv(int x) {
    return qpow(x, mod - 2);
}

