typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAX_N = 200005;
const ll INF = 1e18;

int n;
ll w[MAX_N];
vector<pii> adj[MAX_N];

ll dist[MAX_N];
ll res[MAX_N];

void dfs(int u, int p) {
    for (auto& e : adj[u]) {
        int v = e.first;
        ll len = e.second;
        if (v == p) continue;
        dist[v] = dist[u] + len;
        dfs(v, u);
    }
}

int main() {
