vector<int> d(MAX_N);
vector<pair<int, int>> edges;

void dfs(int u, int p, vector<int>& used) {
    used[u] = 1;
    for (int v : g[u]) {
        if (v == p || used[v]) continue;
        dfs(v, u, used);
    }
}

vector<int> bfs(int start, vector<int>& used) {
    queue<int> q;
    q.push(start);
    used[start] = 1;
    vector<int> res;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        res.push_back(u);
        for (int v : g[u]) {
            if (!used[v]) {
                q.push(v);
                used[v] = 1;
            }
        }
    }
    return res;
}

