    }

    sort(lengths.begin(), lengths.end());
    reverse(lengths.begin(), lengths.end());

    int minCost = INT_MAX;
    minCost = min(minCost, calculateCost(a, b, c, lengths));
    minCost = min(minCost, calculateCostCombination(a, b, c, lengths));

    cout << minCost << endl;

    return 0;
}

