State calNext(const State &s, int dir) {
    State ns = s;
    int zero = 0;
    while (ns.p[zero] != 0) zero++;
    int x = zero / 3, y = zero % 3;
    int nx = x, ny = y;
    if (dir == 0) {
        nx = (x + 1) % 3;
    } else if (dir == 1) {
        nx = (x + 2) % 3;
    } else if (dir == 2) {
        ny = (y + 1) % 3;
    } else if (dir == 3) {
        ny = (y + 2) % 3;
    }
    int nz = nx * 3 + ny;
    swap(ns.p[zero], ns.p[nz]);
    return ns;
}

