double tetrahedronVolume(double a, double b, double c, double d, double e, double f) {
    double s = (a + b + c + d + e + f) / 2;
    return sqrt((s - a) * (s - b) * (s - c) * (s - d) * (s - e) * (s - f)) / 12;
}

