int dfs(int x, int y, stack<char>& st) {
    if (x == h - 1 && y == w - 1) {
        return 0;
    }
    int ret = -1;
    for (int i = 0; i < 2; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (0 <= nx && nx < h && 0 <= ny && ny < w && maze[nx][ny] != '#') {
            char tmp = maze[nx][ny];
            if (tmp >= 'a' && tmp <= 'z') {
                st.push(tmp);
            } else if (tmp >= 'A' && tmp <= 'Z') {
                if (!st.empty() && st.top() == tmp + 32) {
                    st.pop();
                    ret = max(ret, 1 + dfs(nx, ny, st));
                    st.push(tmp + 32);
                } else {
                    ret = max(ret, dfs(nx, ny, st));
                }
            } else {
                ret = max(ret, dfs(nx, ny, st));
            }
            if (tmp >= 'a' && tmp <= 'z') {
                st.pop();
            }
            maze[nx][ny] = '#';
            ret = max(ret, dfs(x, y, st));
            maze[nx][ny] = tmp;
        }
    }
    return ret;
}

