bool hasCycle = false;

void dfs(int node, vector<vector<int>>& graph) {
    visited[node] = true;
    recursionStack[node] = true;

    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            dfs(neighbor, graph);
        } else if (recursionStack[neighbor]) {
            hasCycle = true;
            return;
        }
    }

    recursionStack[node] = false;
}

