    cin >> n >> m;

    vector<int> monsters(n);
    for (int i = 0; i < n; i++) {
        cin >> monsters[i];
    }

    sort(monsters.begin(), monsters.end());

    vector<int> special(m);
    for (int i = 0; i < m; i++) {
        cin >> special[i];
    }

    sort(special.begin(), special.end());

    int ans = 0;

    vector<bool> used(n, false);
    vector<bool> usedSpecial(m, false);

    for (int i = 0; i < m; i++) {
        int best = -1;
        int bestIdx = -1;
        for (int j = 0; j < n; j++) {
            if (used[j]) continue;
            if (monsters[j] == special[i]) {
                best = 1;
                bestIdx = j;
                break;
            }
            int cnt = 0;
            int idx = j;
            while (idx < n && !used[idx] && monsters[idx] < special[i]) {
                cnt++;
                idx++;
            }
            idx = j - 1;
            while (idx >= 0 && !used[idx] && monsters[idx] > special[i]) {
                cnt++;
                idx--;
            }
            if (cnt > best) {
                best = cnt;
                bestIdx = j;
            }
        }
        if (bestIdx != -1) {
            ans++;
            used[bestIdx] = true;
            usedSpecial[i] = true;
            int idx = bestIdx - 1;
            while (idx >= 0 && !used[idx] && monsters[idx] > special[i]) {
                used[idx] = true;
                idx--;
            }
            idx = bestIdx + 1;
            while (idx < n && !used[idx] && monsters[idx] < special[i]) {
                used[idx] = true;
                idx++;
            }
        }
    }

    for (int i = 0; i < m; i++) {
        if (usedSpecial[i]) continue;
        int best = -1;
        int bestIdx = -1;
        for (int j = 0; j < n; j++) {
            if (used[j]) continue;
            int cnt = 0;
            int idx = j;
            while (idx < n && !used[idx]) {
                cnt++;
                idx++;
            }
            idx = j - 1;
            while (idx >= 0 && !used[idx]) {
                cnt++;
                idx--;
            }
            if (cnt > best) {
                best = cnt;
                bestIdx = j;
            }
        }
        if (bestIdx != -1 && best > 0) {
            ans++;
            used[bestIdx] = true;
            int idx = bestIdx - 1;
            while (idx >= 0 && !used[idx]) {
                used[idx] = true;
                idx--;
            }
            idx = bestIdx + 1;
            while (idx < n && !used[idx]) {
                used[idx] = true;
                idx++;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int N = 3e5 + 5;

struct Edge {
    int to, w;
};

vector<Edge> g[N];
vector<int> w, p;
int f[N], ans;

void dfs(int v) {
    if (f[v] != -1) return;
    f[v] = 0;
    for (auto& e : g[v]) {
        dfs(e.to);
        if (e.w > p[v] && f[e.to] + 1 > f[v]) {
            f[v] = f[e.to] + 1;
        }
    }
    ans = max(ans, f[v]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; ++i) {
        int u, v, wi;
        cin >> u >> v >> wi;
        g[u].push_back({v, wi});
        w.push_back(wi);
    }

    sort(w.begin(), w.end());
    w.erase(unique(w.begin(), w.end()), w.end());

    for (int i = 1; i <= n; ++i) {
        p.push_back(-1);
        f[i] = -1;
        for (auto& e : g[i]) {
            int idx = lower_bound(w.begin(), w.end(), e.w) - w.begin();
            e.w = idx;
            p[i] = max(p[i], idx - 1);
        }
    }

    for (int i = 1; i <= n; ++i) {
        dfs(i);
    }

    cout << ans << '\n';

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>

using namespace std;

const int N = 505;
const long long INF = 1e18;

int n, S;
int ini[N], outi[N], wi[N], si[N], vi[N];
vector<int> g[N];

struct Box {
    int w, s, v;
    bool operator<(const Box& other) const {
        return outi[v] < outi[other.v];
    }
};

long long dp[N][N][N];

void dfs(int u, int w, int s) {
    dp[u][w][s] = 0;
    for (auto v : g[u]) {
        int nw = w + wi[v];
        int ns = min(s, si[v]);
        if (nw <= S && ns >= wi[v]) {
            dfs(v, nw, ns);
            dp[u][w][s] = max(dp[u][w][s], dp[v][nw][ns] + vi[v]);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> S;
    for (int i = 1; i <= n; ++i) {
        cin >> ini[i] >> outi[i] >> wi[i] >> si[i] >> vi[i];
    }

    vector<Box> a;
    for (int i = 1; i <= n; ++i) {
        a.push_back({wi[i], si[i], i});
    }
    sort(a.begin(), a.end());

    for (int i = 1; i <= n; ++i) {
        g[i].clear();
    }

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (outi[a[i].v] < ini[a[j].v]) {
                g[a[i].v].push_back(a[j].v);
            }
        }
    }

    memset(dp, -1, sizeof(dp));
