bool dfsa(int x, int ck) {
    if (x == 1) return true;
    if (ca[x]) return false;
    ca[x] = true;
    for (int i : va) {
        if (!dfs(1 - x + i, ck ^ 1)) return true;
    }
    return false;
}

bool dfsb(int x, int ck) {
    if (x == 1) return true;
    if (cb[x]) return false;
    cb[x] = true;
    for (int i : vb) {
        if (!dfs(1 - x + i, ck ^ 1)) return true;
    }
    return false;
}

bool dfs(int x, int ck) {
    if (x <= 0) x += n;
    if (x > n) x -= n;
    if (ck) {
        if (x == 1) return true;
        if (ca[x]) return false;
        ca[x] = true;
        for (int i : va) {
            if (!dfs(1 - x + i, ck ^ 1)) return true;
        }
    } else {
        if (x == 1) return true;
        if (cb[x]) return false;
        cb[x] = true;
        for (int i : vb) {
            if (!dfs(1 - x + i, ck ^ 1)) return true;
        }
    }
    return false;
}

