#include <iostream>
#include <vector>
#include <cmath>
#include <string>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> volumes(n);

    for (int i = 0; i < n; i++) {
        std::cin >> volumes[i];
    }

    double avg = 0.0;
    for (int volume : volumes) {
        avg += volume;
    }
    avg /= n;

    if (std::floor(avg) != avg) {
        std::cout << "Unrecoverable configuration.";
        return 0;
    }

    int occurrences = 0;
    int idx1 = -1, idx2 = -1;

    for (int i = 0; i < n; i++) {
        if (volumes[i] != avg) {
            if (idx1 == -1) idx1 = i + 1;
            else if (idx2 == -1) idx2 = i + 1;
            else {
                std::cout << "Unrecoverable configuration.";
                return 0;
            }
        }
    }

    if (idx1 == -1) {
        std::cout << "Exemplary pages.";
    } else {
        int diff = std::abs(volumes[idx1 - 1] - avg);
        std::cout << diff << " ml. from cup #" << (volumes[idx1 - 1] < avg ? idx1 : idx2) << " to cup #" << (volumes[idx1 - 1] < avg ? idx2 : idx1);
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <algorithm>

using namespace std;

const int MOD = 998244353;

int main() {
    int N;
    cin >> N;

    vector<int> h(2 * N);
    for (int i = 0; i < 2 * N; i++) {
        cin >> h[i];
    }

    sort(h.begin(), h.end());

    map<int, int> count;
    for (int i = 0; i < 2 * N; i++) {
        count[h[i]]++;
    }

    int M = 1;
    for (int i = 1; i <= N; i++) {
        M = (1LL * M * i) % MOD;
    }

    vector<int> fac(N + 1, 1);
    for (int i = 1; i <= N; i++) {
        fac[i] = (1LL * fac[i - 1] * i) % MOD;
    }

    vector<int> invFac(N + 1, 1);
    for (int i = 1; i <= N; i++) {
        invFac[i] = (1LL * invFac[i - 1] * (MOD - MOD / i)) % MOD;
        while (invFac[i] < 0) {
            invFac[i] += MOD;
        }
    }

    int ans = 1;
    for (auto& c : count) {
        if (c.second > N) {
            ans = (1LL * ans * fac[c.second / 2]) % MOD;
            ans = (1LL * ans * invFac[N - c.second / 2]) % MOD;
        } else {
            ans = 0;
            break;
        }
    }

    if (ans == 0) {
        cout << 0 << endl;
        return 0;
    }

    ans = (1LL * ans * M) % MOD;

    for (int i = 2 * N - 1; i >= 1; i--) {
        if (h[i] == h[i - 1]) {
            ans = (1LL * ans * i) % MOD;
        }
    }

    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

using namespace std;

const int MAX_N = 505;

int n;
int p[MAX_N * MAX_N];
bool vis[MAX_N][MAX_N];

int get_x(int x) {
    return (x - 1) / n;
}

int get_y(int x) {
    return (x - 1) % n;
}

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

int ans;

void solve(int x, int y, int dir) {
    if (x < 0 || x >= n || y < 0 || y >= n) return;
    if (vis[x][y]) {
        ans++;
        return;
    }
    vis[x][y] = true;
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (i == dir) solve(nx, ny, i);
        else solve(nx, ny, i);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n * n; i++) {
        cin >> p[i];
        vis[get_x(p[i])][get_y(p[i])] = true;
    }
    ans = 0;
    for (int i = n * n - 1; i >= 0; i--) {
        int x = get_x(p[i]);
        int y = get_y(p[i]);
        vis[x][y] = false;
        for (int j = 0; j < 4; j++) {
            int nx = x + dx[j];
            int ny = y + dy[j];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            solve(nx, ny, j);
        }
    }

    cout << ans << endl;
    return 0;
}

