#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <limits>
#include <cmath>
#include <bitset>

using namespace std;

const int MAX_N = 110;
const int MAX_M = 10;
const int INF = numeric_limits<int>::max();

struct Edge {
    int to, weight;
};

vector<Edge> graph[MAX_N];

int distance[MAX_N][MAX_N];

void floydWarshall(int n) {
    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                distance[i][j] = min(distance[i][j], distance[i][k] + distance[k][j]);
            }
        }
    }
}

void solve() {
    int m, n, k, d;
    cin >> m >> n >> k >> d;

    if (m == 0 && n == 0 && k == 0 && d == 0) return;

    vector<int> cakes(m);
    for (int i = 0; i < m; ++i) cin >> cakes[i];

    for (int i = 0; i < m + n + 2; ++i) {
        graph[i].clear();
        for (int j = 0; j < m + n + 2; ++j) {
            distance[i][j] = INF;
        }
        distance[i][i] = 0;
    }

    for (int i = 0; i < d; ++i) {
        string s, t;
        int e;
        cin >> s >> t >> e;

        int u, v;
        if (s[0] == 'H') u = 0;
        else if (s[0] == 'D') u = m + n + 1;
        else if (s[0] == 'C') u = stoi(s.substr(1)) + 1;
        else u = stoi(s.substr(1)) + m + 1;

        if (t[0] == 'H') v = 0;
        else if (t[0] == 'D') v = m + n + 1;
        else if (t[0] == 'C') v = stoi(t.substr(1)) + 1;
        else v = stoi(t.substr(1)) + m + 1;

        graph[u].push_back({v, e});
        graph[v].push_back({u, e});
    }

    floydWarshall(m + n + 2);

    int ans = numeric_limits<int>::max();
    for (int mask = 0; mask < (1 << m); ++mask) {
        int total = 0;
        int curr = 0;

        for (int i = 0; i < m; ++i) {
            if ((mask & (1 << i)) != 0) {
                total += cakes[i];
                if (i == 0) curr = 1;
                else curr = i + 1;
            }
        }

        int dist = distance[0][curr];
        if (dist != INF) {
            total -= dist * k;
        }

        dist = distance[curr][m + n + 1];
        if (dist != INF) {
            total -= dist * k;
        }

        ans = min(ans, total);
    }

    cout << ans << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (true) {
        solve();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>

using namespace std;

const int MAX_N = 100005;
const int MAX_Q = 100005;
const int INF = INT_MAX;

struct Edge {
    int to, weight;
};

vector<Edge> graph[MAX_N];
int dist[MAX_N][MAX_N];

void dijkstra(int start) {
    vector<int> visited(MAX_N, 0);
    vector<int> distance(MAX_N, INF);
    distance[start] = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        int current = pq.top().second;
        pq.pop();
        if (visited[current]) continue;
        visited[current] = 1;

        for (const Edge& edge : graph[current]) {
            int to = edge.to, weight = edge.weight;
            if (distance[current] + weight < distance[to]) {
                distance[to] = distance[current] + weight;
                pq.push({distance[to], to});
            }
        }
    }

    for (int i = 1; i <= MAX_N; i++) {
        dist[start][i] = distance[i];
    }
}

int main() {
    int N, Q;
    cin >> N >> Q;

    for (int i = 1; i < N; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }

    for (int i = 1; i <= N; i++) {
        dijkstra(i);
    }

    for (int i = 0; i < Q; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        int ans = INF;
        for (int j = 1; j <= N; j++) {
            int maxDist = max(max(dist[a][j], dist[b][j]), dist[c][j]);
            ans = min(ans, maxDist);
        }
        cout << ans << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>

const int N = 1001;

int fib(int i) {
    if (i <= 1) return 1;
    int a = 1, b = 1;
    for (int j = 2; j <= i; j++) {
        int temp = (a + b) % N;
        a = b;
        b = temp;
    }
    return b;
}

int main() {
    int v, d;
    while (std::cin >> v >> d) {
        std::vector<int> f(v + 1);
        std::vector<int> parent(v + 1);
        for (int i = 1; i <= v; i++) {
            f[i] = fib(i);
            parent[i] = i;
        }
        for (int i = 1; i <= v; i++) {
            for (int j = i + 1; j <= v; j++) {
                if (std::abs(f[i] - f[j]) < d) {
                    int x = i, y = j;
                    while (parent[x] != x) x = parent[x];
                    while (parent[y] != y) y = parent[y];
                    if (x != y) parent[y] = x;
                }
            }
        }
