void dfs(int v, int p = -1) {
    sz[v] = 1;
    for (int to : g[v]) {
        if (to == p) continue;
        par[to] = v;
        d[to] = d[v] + 1;
        dfs(to, v);
        sz[v] += sz[to];
    }
}

