using namespace std;

int convertToDecimal(const string& str, int radix) {
    int result = 0;
    int power = 1;
    for (int i = str.size() - 1; i >= 0; i--) {
        char c = str[i];
        int digit = (c >= '0' && c <= '9') ? c - '0' : c - 'A' + 10;
        if (digit >= radix) return -1;
        result += digit * power;
        power *= radix;
    }
    return result;
}

