    cin >> N;
    vector<pair<int, int>> points(N);
    for (int i = 0; i < N; i++) {
        cin >> points[i].first >> points[i].second;
    }

    vector<pair<int, pair<int, int>>> edges;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int cost = min(abs(points[i].first - points[j].first), abs(points[i].second - points[j].second));
            edges.emplace_back(cost, make_pair(i, j));
        }
    }

    sort(edges.begin(), edges.end(), compare);
    DSU dsu(N);
    long long ans = 0;
    for (auto& edge : edges) {
        if (dsu.find(edge.second.first) != dsu.find(edge.second.second)) {
            ans += edge.first;
            dsu.unite(edge.second.first, edge.second.second);
        }
    }

    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>

using namespace std;

const int MAX_N = 100;
const int INF = 1e9;

int N, M;
vector<pair<int, int>> E[MAX_N];
int dist[MAX_N][MAX_N];

void bfs(int s) {
    queue<int> que;
    que.push(s);
    fill(dist[s], dist[s] + N, INF);
    dist[s][s] = 0;

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto e : E[v]) {
            int to = e.first;
            int cost = e.second;

            if (dist[s][v] + cost < dist[s][to]) {
                dist[s][to] = dist[s][v] + cost;
                que.push(to);
            }
        }
    }
}

bool used[MAX_N][MAX_N];

int main() {
    cin >> N >> M;

    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--, b--;

        E[a].emplace_back(b, c);
        E[b].emplace_back(a, c);
    }

    for (int i = 0; i < N; i++) {
        bfs(i);

        for (int j = 0; j < N; j++) {
            for (auto e : E[j]) {
                int to = e.first;
                int cost = e.second;

                if (dist[i][j] + cost == dist[i][to]) {
                    used[i][to] = used[to][i] = true;
                }
            }
        }
    }

    int ans = 0;

    for (int i = 0; i < N; i++) {
        for (auto e : E[i]) {
            int to = e.first;

            if (!used[i][to]) {
                ans++;
            }
        }
    }

    cout << ans / 2 << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <cstdio>

const int MOD = 1000000007;

std::vector<long long> pow3(900005);

void init_pow3() {
    pow3[0] = 1;
    for (int i = 1; i <= 900000; i++) {
        pow3[i] = (pow3[i - 1] * 3) % MOD;
    }
}

long long dp[300005][300005][300005];

long long count_ways(int n, int m, int k) {
    if (n == 0 && m == 0 && k == 0) {
        return 0;
    }
    if (dp[n][m][k] != -1) {
        return dp[n][m][k];
    }
    long long ans = 0;
    if (n > 0) {
        ans += (count_ways(n - 1, m, k) + pow3[m + k]) % MOD;
        ans %= MOD;
    }
    if (m > 0) {
        ans += (count_ways(n, m - 1, k) * 2) % MOD;
        ans %= MOD;
    }
    if (k > 0) {
        ans += (count_ways(n, m, k - 1) * 2) % MOD;
        ans %= MOD;
    }
    return dp[n][m][k] = ans;
}

int main() {
    init_pow3();
    for (int i = 0; i <= 300000; i++) {
        for (int j = 0; j <= 300000; j++) {
            for (int k = 0; k <= 300000; k++) {
                dp[i][j][k] = -1;
            }
        }
    }
    int n, m, k;
    std::cin >> n >> m >> k;
    std::cout << count_ways(n, m, k) << std::endl;
    return 0;
}
